from typing import Optional, Any, Union  # noqa: F401
from taf.internal.aliasing import aliasing_scope
from .facade import RfSwitchFacade


class rf_switch:
    """
    Abstract RF switch controlling library.

    RF switch vendors that are currently supported:
      - ORBIS (models: '24x4', '64x4', '6x6')
      - Keithley (models: 'S46')
      - JFW (models: '50S-1650+XX')
      - NationalInstruments (models: 'PXI-2546', 'PXI-2547', 'PXI-2594', 'PXI-2596')
      - Sinhoo (models: 'CH-R6401-6S')
      - HBTE  (models: 'RFSM-6-65-2-70')
      - JIEXI  (models: 'TSS65B2-6E1-70S-ES', 'TSS32T1-18B1-60S-ES', 'RTS-C001-017', 'TSS8T1-0.1G6-70N-ES',
        'TPS16X-0.4G8.5-60S-P')
      - AGILENT  (models: '34980A')
      - Mini-Circuits (models: All SPDT, SP4T and SP6T except ZTM-15)
      - RFLIGHT (models: 'NT-4X64NS', 'NT-1X64NS', '34980A')
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, store = aliasing_scope(name=__name__,
                                           lookup_arg='rf_switch_device',
                                           lookup_type=RfSwitchFacade)

    def __init__(self):
        self._facade = RfSwitchFacade()

    def setup_rf_switch(self, alias=None, **kwargs):
        # type: (Optional[str], Any) -> None
        """
        Open connection to RF switch.

        | Example usage with tl object from taf.config.testline:
        | ``switch.setup_rf_switch(rf_switch=tl.rf_switches[0], alias=rfs_alias)``
        | Example usage without tl object from taf.config.testline:
        | ``switch.setup_rf_switch(alias='rfs_alias', vendor='Orbis', ip='127.0.0.1', model='24x4')``
        | Example usage with mixed parameters (setup will ignore 'port' param in tl object):
        | ``switch.setup_rf_switch(rf_switch=tl.rf_switches[0], port=3000, alias=rfs_alias)``

        All 'None' value parameters in tl object will be ignored and replaced by default parameters in setup.

        :param str alias: alias to be used in keywords
        :param kwargs: device specific parameters.

          **Mandatory kwargs are: vendor, ip.**

          ORBIS:
            - str vendor: vendor of the RF switch, e.g. "Orbis"
            - str ip: IP address
            - Optional[str] model: model of the RF switch, e.g. "24x4"
            - Optional[str,int] port: ssh port for connection, defaults to 22

          Keithley:
            - str vendor: vendor of the RF switch, e.g. "Keithley"
            - str ip: GPIB (e.g. 'GPIB0')
            - str port: GPIB port (e.g. '6')

          JFW:
            - str ip: IP address
            - Optional[str] model: model of the RF switch, e.g. "50S-1650+XX"

          NationalInstruments:
            - str vendor: vendor of the RF switch, e.g. "NationalInstruments"
            - str ip: IP address
            - Optional[int] port: TCP port
            - Optional[str] model: model of the RF switch, e.g. "PXI-2546"

          Sinhoo:
            - vendor (str): case insensitive, e.g. "Sinhoo"
            - ip (str): IP address
            - port (optional, int or str): port used in connection, defaults to 3000
            - model (optional, str): model of the RF switch, e.g. "CH-R6401-6S"

          JIEXI:
            - vendor (str): case insensitive, e.g. "JIEXI"
            - ip (str): IP address
            - port (optional, int or str): port used in connection, defaults to 3000
            - model (optional, str): model of the RF switch, e.g. "TSS65B2-6E1-70S-ES", "TSS32T1-18B1-60S-ES", "RTS-C001-017", "TSS8T1-0.1G6-70N-ES"

          Agilent:
            - vendor (str): case insensitive, e.g. "Agilent"
            - ip (str): IP address
            - port (optional, int or str): port used in connection, defaults to 5024
            - model (optional, str): model of the RF switch, e.g. "34980A"

          RFLIGHT:
            - str vendor: vendor of the RF switch, e.g. "RFLIGHT"
            - str ip: IP address for connection
            - str,int port: ssh port for connection
            - model (optional, str): model of the RF switch, e.g. NT-4X64NS or 34980A

          Mini-circuits:
            - ip (str): IP address
            - port (optional int): port used in connection, defaults to 80
            - password (str | None): password set for HTTP connection. Defaults to None.

          RPI:
            - ip (str): IP address
            - port (optional int): port used in connection, defaults to 22
            - model (optional, str): model of the IC I/O expanders.
            - username (str): SSH username.
            - password (str): SSH password.

        :raises RuntimeError: when mandatory kwargs are not passed
        """
        self._facade.setup_rf_switch(**kwargs)

        self.store.add(self._facade, alias)

    @lookup_handler.implicit_lookup
    def connect_ports(self, port_in, port_out="1", rf_switch_device=None):
        # type: (str, Union[str, None], Union[str, RfSwitchFacade]) -> None
        """
        Connects input port to output port.
        Currently connect_ports does not support summation or split of the signal.

        :param str port_in: RF switch input port.

          Values should be a str, a representation of a single port.
            - ORBIS:
              -24x4
              Supported values: from 1 to 24, e.g. "1".
              -64x4
              Supported values: from 1 to 64, e.g. "1".
              -6x6
              Supported values: from 1 to 6, e.g. "1".

            - KEITHLEY:
              -S46
              Supported values: from 1 to 24, e.g. "1".

            - JFW:
            Supported values: from 1 to 8, e.g. "4".
            There is additional verification after switching, that the port is indeed connected.
            It is still yet to be tested, how stable are this device's reactions to requests.

            - NationalInstruments:
            Slot should be the used instead,
            since the input port can be deduced rom slot and output.
            E.g. for NationalInstruments PXI-2547 "slot2"

            - Sinhoo:
            Supported values: from 1 to 64, e.g. "1".

            - HBTE:
            Supported values: from 1 to 65, e.g. "1".

            - JIEXI:
              - TSS65
              Supported values: from 1 to 65, e.g. "1".
              - TSS32
              Supported values: from 1 to 32, e.g. "1".
              - RTS:
              Supported values: from 1 to 64, e.g. "1".

            - AGILENT:
            Port_in as string like "111", "222", "141"
            The first character defined as slot which range is 1-8.
            The second character defined as group which range is 1-4.
            The third character defined as port which range is 1-4.

            - RFLIGHT:
              - NT-4X64NS:
                  Supported values: from 1 to 4
              - NT-1X64NS:
                  Supported values: "1" only
              - NT-1X16NS:
                  Supported values: "1" only
              - NT-1X32NS:
                  Supported values: "1" only
              - 34980A:
                  Supported values: from 1 to 64, e.g. "4".

            - Mini-Circuits:
                Rf Switch port that should be connected.

            -RPI:
                Port_in is a string <expander><bank>:<pin>, e.g. 1A:0, 4B:7

        :param str port_out: RF switch output port.

          Values should be a str representation of a single port.
          Defaults to "1".

            - ORBIS:
              -24x4
              ORBIS has 4 outputs, e.g. "1".
              -64x4
              ORBIS has 4 outputs, although only "1" is supported.
              -6x6
              ORBIS has 6 outputs, e.g. "1".

            - Keithley:
              -S46
              Keithley has 1 output, e.g. "1".

            - JFW:
              JFW has only 1 output.

            - NationalInstruments:
              E.g. for NationalInstruments PXI-2547: "ch2B".

            - Sinhoo:
              Sinhoo has only 1 output.

            - HBTE:
              Supported values: from 1 to 2, e.g. "1".

            - JIEXI:
              - TSS65
              RTS has 2 outputs.
              Supported values: from 1 to 2, e.g. "1".
              - TSS32
              RTS has only 1 output.
              - RTS:
              RTS has only 1 output.
              - TSS8T1:
              TSS8T1 has only 1 output.

            - AGILENT:
            Port_out as string like "111", "221", "141"
            The first character defined as slot which range is 1-8.
            The second character defined as group which range is 1-4.
            The third character defined as port which default as 1.

            - RFLIGHT:
              - NT-4X64NS:
                  Supported values: from 0 to 64
              - NT-1X64NS:
                  Supported values: from 0 to 64
              - NT-1X16NS:
                  Supported values: from 0 to 16
              - NT-1X32NS:
                  Supported values: from 0 to 32
              - 34980A:
                Has only 1 output

            - Mini-Circuits:
              - Rf Switch ID.

            - RPI:
            RPI does not currently support port_out.
            A value can be passed, but it will not affect functionality.

        :param Union[str,RfSwitchFacade] rf_switch_device: can be a string name alias or RfSwitchFacade object
        :raises RfSwitchActionFailed: if RF switch is unable to perform requested action
        """
        if port_in is not None:
            port_in = str(port_in)
        if port_out is not None:
            port_out = str(port_out)
        rf_switch_device.connect_ports(port_in, port_out)

    @lookup_handler.implicit_lookup
    def disconnect_ports(self, port_in, port_out="1", rf_switch_device=None):
        # type: (str, Union[str, None], Union[str, RfSwitchFacade]) -> None
        """
        Disconnects input port from output port.
        Check connect_ports method doc for details.
        :raises RfSwitchActionNotSupported:
            - model NT-4X64NS of RFLIGHT does not support this function now.
            - all Mini-Circuits SPDT models does not support this function.
        """
        port_in = str(port_in)
        if port_out is not None:
            port_out = str(port_out)
        rf_switch_device.disconnect_ports(port_in, port_out)

    @lookup_handler.implicit_lookup
    def get_port_in_status(self, port_in, rf_switch_device=None):
        # type: (str, Union[str, RfSwitchFacade]) -> Union[str, None]
        """
        Get RF switch input port status.

        **NationalInstruments does not support this function now.**
        **ORBIS does not support this function now,
        because the functionality described in device manual works incorrectly**
        **RFLIGHT models NT-4X64NS, NT-1X64NS, NT-1X16NS, NT-1X32NS does not support this function now.**
        **Mini-Circuits models doesn't support this function.**
        **RPI models doesn't support this function.**

        :param str port_in: RF switch input port.

          - JFW:
          Supported values: from 1 to 8, e.g. "4".

          - Sinhoo:
          Supported values: from "1" to "64", e.g. "1".

          - HBTE:
          Supported values: from "1" to "65", e.g. "1".

          - RFLight:
            - NT-4X64NS:
              :raises RfSwitchActionNotSupported: model does not support this function now
            - NT-1X64NS:
              :raises RfSwitchActionNotSupported: model does not support this function now
            - NT-1X16NS:
              :raises RfSwitchActionNotSupported: model does not support this function now
            - NT-1X32NS:
              :raises RfSwitchActionNotSupported: model does not support this function now
            - 34980A:
              Supported values: from "1" to "65", e.g. "1".

          - JIEXI:
            -TSS65
            Does not support this funciton
            -TSS32:
            Supported values: from "1" to "32", e.g. "1".
            -RTS:
            Supported values: from "1" to "64", e.g. "1".
            -TSS8T1:
            Supported values: from "1" to "8", e.g. "1".

          - AGILENT:
            Port_in as string like "111", "222", "141"
            The first character defined as slot which range is 1-8.
            The second character defined as group which range is 1-4.
            The third character defined as port which range is 1-4.

        :param Union[str,RfSwitchFacade] rf_switch_device: can be a string name alias or RfSwitchFacade object
        :return Union[str,None]: if port_in is connected to port_out- returns port_out, None otherwise.

        :raise RfSwitchActionFailed: if RF switch is unable to perform requested action
        :raise RfSwitchNotImplementedError: if RF switch does not support this action
        """
        port_in = str(port_in)
        return rf_switch_device.get_port_in_status(port_in)

    @lookup_handler.implicit_lookup
    def get_port_out_status(self, port_out=None, rf_switch_device=None):
        # type: (str, Union[str, RfSwitchFacade]) -> Union[str, None]
        """
        Get RF switch output port status.

        **NationalInstruments does not support this function now.**
        **ORBIS does not support this function now,
        because the functionality described in device manual works incorrectly**
        **RFLIGHT models NT-4X64NS, NT-1X64NS, NT-1X16NS, NT-1X32NS does not support this function now.**
        **RPI does not support this function now.**

        :param str port_out: RF switch output port.

          - Sinhoo, JFW:
            It has only 1 output.
            Defaults to "1".

          - HBTE:
            Supported values: from 1 to 2, e.g. "1".

          - HBTE:
            Supported values: only "1".

          - JIEXI:
            - TSS65
            Does not support this funciton
            - TSS32
            Defaults to "1".
            RTS has only 1 output.
            - RTS:
            RTS has only 1 output.
            Defaults to "1".
            - TSS8T1:
            TSS8T1 has only 1 output.
            Defaults to "1".

          - AGILENT:
            Port_out as string like "111", "221", "141"
            The first character defined as slot which range is 1-8.
            The second character defined as group which range is 1-4.
            The third character defined as port which default as 1.

          - Mini-Circuits:
            Rf Switch ID.

        :param Union[str,RfSwitchFacade] rf_switch_device: can be a string name alias or RfSwitchFacade object
        :return Union[str,None]: if port_out is connected to port_in- returns port_out, None otherwise.

          - Sinhoo, JFW:
            port_out is always connected to some port_in,
            therefore it always returns a port_in

          - HBTE:
            port_out is always connected to some port_in,
            therefore it always returns a port_in

          - JIEXI:
            - TSS65
            Does not support this funciton
            - TSS32:
            port_out is always connected to some port_in,
            therefore it always returns a port_in
            - RTS:
            port_out is always connected to some port_in,
            therefore it always returns a port_in
            - TSS8T1:
            port_out is always connected to some port_in,
            therefore it always returns a port_in

            - AGILENT:
            port_out is always connected to some port_in,
            therefore it always returns a port_in

            - RFLight
              - NT-4X64NS
              :raises RfSwitchActionNotSupported: model does not support this function now
              - NT-1X64NS
              :raises RfSwitchActionNotSupported: model does not support this function now
              - NT-1X16NS
              :raises RfSwitchActionNotSupported: model does not support this function now
              - NT-1X32NS
              :raises RfSwitchActionNotSupported: model does not support this function now

            - Mini-Circuits:
                - return port number that is connected to specified switch.

        :raises RfSwitchActionFailed: if RF switch is unable to perform requested action
        :raises RfSwitchNotImplementedError: if RF switch does not support this action
        """
        if port_out is not None:
            port_out = str(port_out)
        return rf_switch_device.get_port_out_status(port_out)

    @lookup_handler.implicit_lookup
    def get_connected_ports(self, rf_switch_device=None):
        # type: (Union[str, RfSwitchFacade]) -> dict[str, str]
        """
        Returns currently connected ports, in form of dict,
        where key is port_in, value is port_out.

        **NationalInstruments does not support this function now.**
        **ORBIS does not support this function now,
        because the functionality described in device manual works incorrectly**
          - Sinhoo, JFW:
            port_out is always connected with port_in,
            therefore it always returns dict like: {"1": "1"}

          - HBTE:
            port_out is always connected with port_in,
            therefore it always returns dict like: {"1": "1"}

          - JIEXI:
            - TSS65
            does not support this funciton
            - TSS32:
            port_out is always connected with port_in,
            therefore it always returns dict like: {"1": "1"}
            - RTS
            port_out is always connected with port_in,
            therefore it always returns dict like: {"1": "1"}
            - TSS8T1
            port_out is always connected with port_in,
            therefore it always returns dict like: {"1": "1"}

            - RFLIGHT:
              - NT-4X64NS:
                returns current configuration of ports as dict
              - NT-1X64NS:
                returns current configuration of ports as dict
              - NT-1X16NS:
                returns current configuration of ports as dict
              - NT-1X32NS:
                returns current configuration of ports as dict
              - 34980A:
                returns current configuration of ports as dict
          - Mini-circuits:
                For mini-circuits devices, get_connected_ports returns different dictionary structure,
                than for other switches {port_in: port_out}:
                    - keys are the port_out values instead of port_in
                    - values are the port_in values instead of port_out
                This is caused due to the device specific - it can contain multiple switches,
                which are mapped by port_out. Each switch has same port_in value ranges,
                so the key's wouldn't be unique in for the standard dict structure.
                Example of return value: {"A": "1"}
          - RPI:
                As RPI does not yet support changing port_out, returns list of port_in that are currently set high.
                Ports are in format: <expander><bank>:<pin>, e.g. 1A:0, 4B:7

        :param Union[str,RfSwitchFacade] rf_switch_device: can be a string name alias or RfSwitchFacade object
        :return: dict[str,str]: connected ports, key is port_in, value is port_out

        :raises RfSwitchActionFailed: if RF switch is unable to perform requested action
        :raises RfSwitchNotImplementedError: if RF switch does not support this action
        """
        return rf_switch_device.get_connected_ports()
